numbers = list(range(1, 1001))
def linear_search(items, target):
    count = 0
    for item in items:
        count += 1
        if item == target:
            return count
    return count

def binary_search(items, target):
    left, right = 0, len(items) - 1
    count = 0
    while left <= right:
        mid = (left + right) // 2
        count += 1
        if items[mid] == target:
            return count
        if items[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return count
print("Linear comparisons:", linear_search(numbers, 999))
print("Binary comparisons:", binary_search(numbers, 999))
